    tu: ["un podomètre (nom masculin) : máy đếm bước", "un bénéfice (nom masculin) : lợi ích", "un seuil (nom masculin) : ngưỡng", "se décourager (verbe) : nản lòng", "l'intensité (nom féminin) : cường độ"],
    meo: ["Lời chuyên gia hay đi theo: phá một niềm tin sai → điều khoa học nói → lời khuyên. Từ « Or » báo hiệu phần phá niềm tin.", "Nghe một lần: khi nghe « Mon conseil, donc », chuẩn bị bắt câu trả lời cho câu hỏi về lời khuyên."],
    pt: { loai: "Chuyên gia trả lời câu hỏi thính giả", chu_de: "Có thật cần đi bộ 10 000 bước mỗi ngày?", y: ["Con số 10 000 bước không đến từ khoa học mà từ quảng cáo máy đếm bước ở Nhật những năm 1960.", "Lợi ích rõ đã có từ 6 000 đến 8 000 bước/ngày (giảm nguy cơ bệnh tim).", "Trên ngưỡng đó vẫn có lợi nhưng tăng chậm.", "Lời khuyên: đều đặn là chính, đi nhanh một phần thời gian vì cường độ cũng quan trọng."] },
