    tu: ["pousser la porte (locution) : bước vào lần đầu", "à condition que (locution) : với điều kiện là", "tenir (verbe) : trụ vững", "lancer un appel (locution) : kêu gọi", "chargé (adjectif) : quá đông, quá tải"],
    meo: ["Câu hỏi « but de l'orateur »: nghe các động từ nói về hành động lời nói (« remercier », « lancer un appel »), chúng cho biết mục đích từng phần.", "« Mais je voudrais aussi… » chuyển từ cảm ơn sang phần quan trọng nhất của bài phát biểu."],
    pt: { loai: "Bài phát biểu ngắn", chu_de: "Lời chia tay của một cô giáo nghỉ hưu sau 30 năm.", y: ["Ngày đầu là cô giáo trẻ nhiều băn khoăn; nay chắc chắn đây là nghề đẹp nhất nếu có đủ điều kiện.", "Cảm ơn phụ huynh và nhất là đồng nghiệp.", "Kêu gọi: lớp quá đông, thiếu giáo viên dạy thay, đừng để trường thành nơi « sống sót » thay vì học.", "Có thể quay lại làm tình nguyện viên ở thư viện."] },
