    tu: ["au volant (locution) : khi đang lái xe", "vibrer (verbe) : rung", "hors de portée (locution) : ngoài tầm tay", "un usager de la route (nom masculin) : người tham gia giao thông", "relever la tête (locution) : ngẩng đầu lên"],
    meo: ["Quảng cáo xã hội luôn có: tình huống → số liệu gây sốc → lời khuyên → tên tổ chức. Đoán trước câu hỏi sẽ rơi vào số liệu và lời khuyên.", "Phân biệt các con số gần nhau (14 mét, 23 lần, 50 km/h): ghi số kèm một chữ để khỏi lẫn."],
    pt: { loai: "Quảng cáo phòng ngừa trên radio", chu_de: "Không đọc tin nhắn khi lái xe.", y: ["Một giây ở 50 km/h là 14 mét đi như nhắm mắt.", "14 mét có thể là vạch qua đường, một đứa trẻ, một chiếc xe đạp.", "Đọc tin nhắn khi lái làm nguy cơ tai nạn tăng 23 lần.", "Lời khuyên: bật chế độ lái xe hoặc cất điện thoại ngoài tầm tay; tin nhắn có thể chờ."] },
